// seed: tests/seed.spec.ts (гость) · прод, только чтение (запись заблокирована); в попапе — только «המשך בלי הרשמה».
import { test, expect } from '@playwright/test';
import { prepareGuest, loginPopup, readRedirectAfterLogin, LISTING_ID, LISTING_URL, LOAD } from './contact-popup.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Текст попапа входа у гостя', () => {
  test('«המשך בלי הרשמה»: попап закрыт, остаёмся на объявлении, возврат не записан #565d74 @android @prod-safe', async ({ page }) => {
    await prepareGuest(page);
    await page.goto(LISTING_URL);

    await page.getByRole('button', { name: 'הצג מספר טלפון' }).first().click({ timeout: LOAD.timeout });
    const popup = loginPopup(page);
    await expect(popup, 'открылся попап входа').toBeVisible(LOAD);

    await popup.getByRole('button', { name: 'המשך בלי הרשמה' }).click();

    await expect(popup, 'попап закрылся').toBeHidden();
    const url = new URL(page.url());
    expect(url.pathname, 'остались на странице объявления').toBe('/businessdetail');
    expect(url.searchParams.get('id'), 'то же объявление').toBe(LISTING_ID);
    expect(await readRedirectAfterLogin(page), 'redirectAfterLogin не записан').toBeNull();
  });
});
